use super::*;
use crate::account::Kind;

/// Utilisation across every credit line together — the figure a score actually reads.
pub fn overall_utilisation(p: &Position) -> Option<f64> {
    let lines: Vec<&AccountPosition> = p.accounts.iter().filter(|a| a.kind == Kind::Credit && a.credit_limit.is_some()).collect();
    let limit: i64 = lines.iter().map(|a| a.credit_limit.unwrap().minor).sum();
    if limit <= 0 {
        return None;
    }
    let owed: i64 = lines.iter().map(|a| a.owed.map(|o| o.minor).unwrap_or(0)).sum();
    Some(round3(owed as f64 / limit as f64))
}
